+  <div id="projectList"></div>
+
+  <script>
+    const apiBase = '/api/projects';
+    const alertDiv = document.getElementById('alert');
+    const projectListDiv = document.getElementById('projectList');
+
+    function showAlert(message) {
+      alertDiv.textContent = message;
+      alertDiv.style.display = 'block';
+    }
+
+    function clearAlert() {
+      alertDiv.style.display = 'none';
+    }
+
+    async function loadProjects() {
+      const resp = await fetch(apiBase);
+      const projects = await resp.json();
+      renderProjects(projects);
+    }
+
+    function renderProjects(projects) {
+      projectListDiv.innerHTML = projects
+        .map(p => `
+          <div class="project-row" data-testid="project-row"><span class="project-name">${p.name}</span><button class="open-btn" data-id="${p.id}">Open project</button></div>
+        `)
+        .join('');
+      document.querySelectorAll('.open-btn').forEach(btn => {
+        btn.addEventListener('click', () => {
+          const id = btn.getAttribute('data-id');
+          window.location.href = `/projects/${id}`;
+        });
+      });
+    }
+
+    document.getElementById('createBtn').addEventListener('click', async () => {
+      clearAlert();
+      const nameInput = document.getElementById('projectNameInput');
+      const name = nameInput.value.trim();
+      if (!name) {
+        showAlert('Project name is required');
+        return;
+      }
+      const resp = await fetch(apiBase, {
+        method: 'POST',
+        headers: { 'Content-Type': 'application/json' },
+        body: JSON.stringify({ name })
+      });
+      if (!resp.ok) {
+        const err = await resp.json();
+        showAlert(err.error || 'Error');
+        return;
+      }
+      nameInput.value = '';
+      await loadProjects();
+    });
+
+    // Initial load
+    loadProjects();
